import {projectValidation as trial} from './data/project-validation.js';
import {projects,projectStages,capabilityMap} from './data/projects.js';
import {projectStatus} from './project-state.js';
import {escapeHTML as e} from './state.js';

const link=s=>`#/projects/${s.id}`;
const stageCard=(s,state)=>{const status=projectStatus(s,state);return `<a class="project-stage-card" href="${link(s)}"><span class="eyebrow">WEEK ${s.week} · ${s.minutes} 分钟起，可拆成多次</span><h3>${e(s.title)}</h3><p>${e(s.goal)}</p><span class="badge">${status.completed?'机制验证通过':'开始 / 继续带练'}</span>${status.hasNotes?'<span class="small muted"> · 已记实验观察</span>':''}</a>`;};
export function projectsHome(state){
 const done=projectStages.filter(s=>projectStatus(s,state).completed).length;
 const next=projectStages.find(s=>!projectStatus(s,state).completed)||projectStages[0];
 return `<div class="page-heading"><div><h1>项目实战</h1><p>从一个能手算的世界出发，亲手构建、测量，再读懂 OmniFM。</p></div></div>
 <section class="panel project-hero"><span class="eyebrow">BUILD → EXPLAIN → VERIFY</span><h2>每次增加一个组件，都回答：为什么需要它？</h2><p>16 关带练，连接现有 12 周课程。先看具体问题与推演，再写可自动检查的 Python；本地训练产出指标和权重，最后回到真实项目寻找对应设计。</p><div class="row wrap"><a class="btn btn-primary" href="${link(next)}">${done?'继续下一关':'从第 01 关开始'} →</a><a class="btn" href="./downloads/model-craft-projects.zip" download>下载实战代码包</a><span class="small">${done} / ${projectStages.length} 关机制验证</span></div></section>
 <div class="project-overview-grid">${projects.map(p=>`<section class="panel panel-pad"><span class="eyebrow">${e(p.tag)}</span><h2>${e(p.title)}</h2><p>${e(p.description)}</p><p class="small"><b>交付：</b>${e(p.deliverable)}</p><a class="text-link" href="${link(projectStages.find(s=>s.projectId===p.id))}">${e(p.range)} · 进入项目 →</a></section>`).join('')}</div>
 <section class="panel panel-pad project-validation"><span class="eyebrow">已实际运行的教学基线 · ${e(trial.date)}</span><h2>先看一次真实结果，再亲手复验</h2><p>${e(trial.device)} · PyTorch ${e(trial.torch)} · seed=${trial.seed} · ${trial.steps} 步。这里是验证集 8 步闭环 MSE，越低越好；你的结果可能不同。</p><div class="table-wrap"><table><thead><tr><th>模型</th><th>观测</th><th>参数数</th><th>训练前</th><th>训练后</th><th>保持不动基线</th></tr></thead><tbody>${trial.rows.map(r=>`<tr><td>${e(r.arch)}</td><td>${r.observation==='full'?'位置 + 速度':'只有位置'}</td><td>${r.parameters.toLocaleString()}</td><td>${r.before.toFixed(4)}</td><td>${r.after.toFixed(4)}</td><td>${r.persistence.toFixed(4)}</td></tr>`).join('')}</tbody></table></div><p class="small">先比较相同观测条件的后三行：历史有帮助，更多参数却不保证这个预算下更优。第一行输入多了速度，且误差平均位置/速度两个输出维度；后三行只评位置，不能跨这两组直接比较误差。单个 seed、等步数不等算力；这些是原始观察，不是通用排名。</p><details><summary>核对试跑代码版本</summary><p class="mono source-hash">lab.py SHA256：${e(trial.source_sha256)}</p><p>源码位于下载包 projects/world-lab/lab.py。训练命令见对应关卡；展示值不会计入你的个人进度。</p></details></section>
 <section class="panel panel-pad"><h2>每天怎么做，三个月怎么推进</h2><p>以项目替换当天相应的编程时间，不叠加两套完整作业。30 分钟完成一个讲解或机制题；有 60–120 分钟时做本地实验。序号表示依赖顺序，周数是建议窗口。遇到不懂的术语，在关卡内先学，再按需返回已有课程。</p><ol class="project-schedule"><li><b>第 1–4 周：</b>数据契约 → 基线 → MLP 训练 → 因果序列；先能解释一次更新。</li><li><b>第 5–8 周：</b>闭环 rollout、视觉表示与记忆；穿插 SFT / LoRA 小任务。重训练可以跨日等待。</li><li><b>第 9–12 周：</b>恢复、推理、性能与消融；选一个真实 run 串起 OmniFM，整理转岗作品。</li></ol><p class="callout">目标是具备可验证的训练、诊断和实验能力。三个月不能穷尽所有模型；未实际跑通的视觉、KDA GPU、多卡与服务实验会明确保留待做状态。网页通关不会自动变成岗位能力认证。</p></section>
 ${projects.map(p=>`<section class="project-track"><div class="page-heading"><div><span class="eyebrow">${e(p.range)}</span><h2>${e(p.title)}</h2></div></div><div class="project-stage-grid">${projectStages.filter(s=>s.projectId===p.id).map(s=>stageCard(s,state)).join('')}</div></section>`).join('')}
 <section class="panel panel-pad"><h2>主流方法在这里如何归位</h2><div class="table-wrap"><table><thead><tr><th>能力 / 方法</th><th>实战覆盖与边界</th><th>配套课程</th></tr></thead><tbody>${capabilityMap.map(([name,scope,lesson])=>`<tr><td>${e(name)}</td><td>${e(scope)}</td><td><a href="#/lesson/${lesson}">回看讲解 →</a></td></tr>`).join('')}</tbody></table></div><p>PT 必须结合上下文确定是 pretraining 还是别的缩写；rewardx 与 LSD 不凭名称猜测。项目特定术语放回配置、代码和日志中核对。</p></section>`;
}

export function projectCompletion(stage,state){
 const s=projectStatus(stage,state);
 return `<div class="between wrap"><div><h3>${s.completed?'本关机制验证通过':'本关机制检查'}</h3><p class="small">讲解 ${s.taught?'✓':'待走完'} · 判断题 ${s.quiz?'✓':'待修正'} · 当前代码 ${s.code?'✓':'待完整提交'}${s.usedSolution?' · 看过参考解法':''}</p></div><button class="btn btn-primary" data-action="project-complete" data-id="${stage.id}" ${s.ready?'':'disabled'}>${s.completed?'重新记录通过':'记录机制验证通过'}</button></div><p class="small muted">本地训练单独记实验事实；样例运行、文本笔记和导入报告都不会自动判为实战完成。改代码后需要重新提交。</p>`;
}

export function projectStagePage(stage,state,editor){
 const project=projects.find(p=>p.id===stage.projectId),record=state.projects?.[stage.id]||{},step=record.step||0;
 const index=projectStages.indexOf(stage),next=projectStages[index+1],prev=projectStages[index-1];
 const panels=[['先看一个具体问题',[stage.story]],['新概念如何解释这个问题',stage.explanation],['为什么这样设计',[stage.decision,'备选方案与代价：'+stage.alternative]],['一起手算一次',stage.walkthrough]];
 const [title,paragraphs]=panels[step];
 return `<div class="project-breadcrumb"><a href="#/projects">项目实战</a><span> / ${e(project.title)}</span></div><div class="page-heading"><div><h1>${e(stage.title)}</h1><p>${e(stage.goal)}</p></div></div>
 <div class="project-step-layout"><aside class="panel project-side"><span class="eyebrow">带练路径</span>${projectStages.filter(s=>s.projectId===stage.projectId).map(s=>`<a class="${s.id===stage.id?'active':''}" href="${link(s)}" ${s.id===stage.id?'aria-current="page"':''}>${projectStatus(s,state).completed?'✓ ':''}${e(s.title)}</a>`).join('')}<hr><a href="#project-learn" data-action="lesson-section" data-id="project-learn">1. 一步一步讲</a><a href="#project-question" data-action="lesson-section" data-id="project-question">2. 即时判断</a><a href="#project-code" data-action="lesson-section" data-id="project-code">3. 亲手写代码</a><a href="#project-local" data-action="lesson-section" data-id="project-local">4. 本地做实验</a><a href="#project-notes" data-action="lesson-section" data-id="project-notes">5. 留下实验记录</a></aside><div class="stack">
 <section id="project-learn" class="panel panel-pad" tabindex="-1"><div class="between"><span class="eyebrow">带练 ${step+1} / 4</span><span class="small">每关可以分多次完成 · 自动保存位置</span></div><div class="project-step-tabs" role="group" aria-label="讲解步骤">${panels.map(([name],i)=>`<button class="btn btn-small ${step===i?'btn-primary':''}" data-action="project-step" data-id="${stage.id}" data-index="${i}" aria-pressed="${step===i}">${i+1}. ${e(name)}</button>`).join('')}</div><h2>${e(title)}</h2>${paragraphs.map(p=>`<p class="project-prose">${e(p)}</p>`).join('')}<div class="row wrap">${step>0?`<button class="btn" data-action="project-step" data-id="${stage.id}" data-index="${step-1}">← 上一步</button>`:''}${step<3?`<button class="btn btn-primary" data-action="project-step" data-id="${stage.id}" data-index="${step+1}">继续推演 →</button>`:'<button class="btn btn-primary" data-action="lesson-section" data-id="project-question">试着判断 →</button>'}</div></section>
 <section class="panel panel-pad" id="project-question" tabindex="-1"><h2>先判断，再解释</h2><form class="project-question" data-stage="${stage.id}"><fieldset><legend>${e(stage.check.prompt)}</legend>${stage.check.options.map((o,i)=>`<label class="project-option"><input type="radio" name="answer" value="${i}" ${record.selected===i?'checked':''} required><span>${e(o)}</span></label>`).join('')}</fieldset><button class="btn btn-primary" type="submit">检查我的理解</button></form>${Number.isInteger(record.selected)?`<div class="callout" role="status"><b>${record.selected===stage.check.answer?'理解正确':'再想一想'}</b><p>${e(stage.check.explanation)}</p></div>`:''}</section>
 <section class="panel panel-pad" id="project-code" tabindex="-1"><span class="eyebrow">浏览器内真实 PYTHON · 约 30 分钟</span><h2>把这个设计写出来</h2>${editor}</section>
 <section class="panel panel-pad" id="project-local" tabindex="-1"><span class="eyebrow">本机 / GPU 实验 · 与网页机制题分开记录</span><h2>从小机制回到完整项目</h2><p>先在仓库根目录创建 Python 虚拟环境并安装 PyTorch，详见代码包 README。命令中的 python3 应指向该环境。输出统一写入已忽略的 .openai/local/。</p><pre class="project-command"><code>${e(stage.command)}</code></pre>${stage.commandNote?`<p class="callout">${e(stage.commandNote)}</p>`:''}<ol class="project-experiment">${stage.experiment.map(item=>`<li>${e(item)}</li>`).join('')}</ol><h3>应看到的结果与边界</h3><p>${e(stage.expected)}</p><h3>如果结果不符合预期</h3><p>${e(stage.failure)}</p><h3>迁移到 OmniFM 时看什么</h3><p>${e(stage.transfer)}</p><div class="row wrap"><a class="btn" href="./downloads/model-craft-projects.zip" download>下载代码与运行指南</a><a class="btn" href="https://github.com/TatenLee/model-craft/tree/main/projects" target="_blank" rel="noopener noreferrer">查看项目源码 ↗</a></div></section>
 ${stage.id==='omnifm-audit'?`<section class="panel panel-pad"><h2>打开本地 OmniFM 阅读索引</h2><p>选择 .openai/local/omnifm-map.json。只在当前页面内存显示相对路径与符号，不上传、不存入学习备份，刷新即清除。索引证明代码位置，不能证明启用配置。</p><label class="btn">选择本地索引<input id="project-source-file" type="file" accept=".json,application/json"></label><div id="project-source-result" aria-live="polite"></div></section>`:''}
 <section class="panel panel-pad" id="project-notes" tabindex="-1"><h2>带着结果回来，我们继续诊断</h2><p>四句话就够：预期什么、实际观察什么、可能原因、下一次只改什么。遇到错误可以复制“带练交接单”给我，继续逐步排查。这里没有 GPT 自动评分或隐藏账号依赖。</p><div class="project-notes-grid">${[['hypothesis','我的假设 / 本次只改的变量'],['observation','实际观察 / 指标 / 错误信息'],['explanation','我怎样解释，哪里还不确定'],['next','下一步验证什么']].map(([key,label])=>`<label>${label}<textarea class="field project-note" data-stage="${stage.id}" data-field="${key}" rows="4" placeholder="只记录实际观察；还没做可以留空">${e(record.notes?.[key]||'')}</textarea></label>`).join('')}</div><p class="small muted" id="project-note-status">仅保存到本机；可通过“进度备份与设置”导出。不要在公开交接单中粘贴公司数据。</p><button class="btn" data-action="project-export" data-id="${stage.id}">下载带练交接单</button><hr><h3>导入世界模型训练报告，对照你的解释</h3><p class="small">仅在内存展示，不上传、不修改通关状态。它是你提供的报告，不是平台验证过的训练证明。</p><label class="btn">选择 report.json<input id="project-report-file" type="file" accept=".json,application/json"></label><div id="project-report-result" aria-live="polite"></div></section>
 <section class="panel panel-pad" id="project-completion">${projectCompletion(stage,state)}</section>
 <details class="panel panel-pad"><summary>需要时再查：配套课文与原始依据</summary><div class="row wrap space-top">${stage.links.map(id=>`<a class="btn btn-small" href="#/lesson/${id}">${id} 讲解</a>`).join('')}${stage.sources.map(s=>`<a class="source-link" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a>`).join('')}</div></details><div class="between wrap">${prev?`<a class="btn" href="${link(prev)}">← ${e(prev.title)}</a>`:'<a class="btn" href="#/projects">返回项目地图</a>'}${next?`<a class="btn" href="${link(next)}">${e(next.title)} →</a>`:'<a class="btn" href="#/projects">查看交付清单 →</a>'}</div></div></div>`;
}
export function reportHTML(r){
 return `<div class="callout"><b>已读取自报实验：${e(r.config.arch)} / ${e(r.config.observation)}</b><p>seed ${r.config.seed} · ${r.step} 步 · width ${r.config.width} · lr ${r.config.lr} · batch ${r.config.batch_size} · ${r.parameters} 参数 · ${e(r.device)}</p><p>验证单步 MSE ${r.validation.one_step_mse.toPrecision(4)} · rollout MSE ${r.validation.rollout_mse.toPrecision(4)} · persistence ${r.validation.persistence_rollout_mse.toPrecision(4)}</p><p>整段前向 p50 ${r.latency.p50_ms.toFixed(2)}ms / p95 ${r.latency.p95_ms.toFixed(2)}ms；无 cache，不是服务 TTFT。</p><p class="small mono">代码 SHA256：${e(r.source_sha256)}</p></div>`;
}
export function sourceHTML(r){
 return `<p>本地 revision：<code>${e(r.revision)}</code>${r.dirty?' · 工作树有改动':''}。当前实际训练配置：<b>未验证</b>。</p>${Object.entries(r.groups).map(([group,rows])=>`<details><summary>${e(group)} · ${rows.length} 个候选符号</summary><ul>${rows.map(row=>`<li><code>${e(row.file)}:${row.line}</code> — ${e(row.symbol)}<small class="source-hash">文件 SHA256：${e(row.sha256)}</small></li>`).join('')}</ul></details>`).join('')}`;
}
